#[test]
fn test_an_in_memory_source_reads_like_a_blob() {
    let s: &crate::port::Src = &crate::port::src_of_blob(&crate::testport::text_blob("0123456789")[..]);
    crate::testport::assert_eq(crate::port::src_len(s), 10, "length");
    crate::testport::assert_eq(crate::port::src_u8(s, 0), 48, "first byte");
    crate::testport::assert_eq(crate::port::src_u8(s, 9), 57, "last byte");
    crate::testport::assert_eq(crate::port::blob_len(&crate::port::src_slice(s, 2, 5)[..]), 3, "a span's length");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(s, 2, 5)[..], 0), 50, "a span's first byte");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(s, 2, 5)[..], 2), 52, "a span's last byte");
    crate::testport::assert_eq(crate::port::blob_len(&crate::port::src_slice(s, 4, 4)[..]), 0, "an empty span");
    crate::testport::assert_eq(crate::port::blob_len(&crate::port::src_slice(s, 0, 10)[..]), 10, "the whole source");
    crate::port::src_hint(s, 0, 5);
    crate::testport::assert_eq(crate::port::src_u8(s, 3), 51, "a hint changes nothing");
    crate::testport::assert_eq(st_m(s), 0, "an in-memory source never misses");
}
#[test]
fn test_bytes_above_127_are_not_negative() {
    let s: &crate::port::Src = &crate::port::src_of_blob(&crate::testport::hex_blob("00ff80")[..]);
    crate::testport::assert_eq(crate::port::src_u8(s, 1), 255, "ff");
    crate::testport::assert_eq(crate::port::src_u8(s, 2), 128, "80");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(s, 1, 3)[..], 0), 255, "ff in a span");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(s, 1, 3)[..], 1), 128, "80 in a span");
}
#[test]
fn test_a_source_of_cells_takes_the_low_eight_bits() {
    let c: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(c, 7);
    crate::port::cells_push(c, 300);
    crate::port::cells_push(c, 255);
    crate::testport::assert_eq(crate::port::src_len(&crate::port::src_of_cells(c)), 3, "length");
    crate::testport::assert_eq(crate::port::src_u8(&crate::port::src_of_cells(c), 0), 7, "first");
    crate::testport::assert_eq(crate::port::src_u8(&crate::port::src_of_cells(c), 1), 44, "300 is 0x12c: 0x2c");
    crate::testport::assert_eq(crate::port::src_u8(&crate::port::src_of_cells(c), 2), 255, "last");
    crate::testport::assert_eq(st_m(&crate::port::src_of_cells(c)), 0, "never misses");
}
#[test]
fn test_a_read_in_a_missing_chunk_answers_zero_and_sets_the_flag() {
    let base: &crate::port::Src = &crate::testport::src_chunked(&crate::testport::text_blob("0123456789abcdef")[..], 4, 0);
    let v: &crate::port::Src = &crate::testport::src_view(base);
    crate::testport::assert_eq(crate::port::src_len(v), 16, "the length is known before any byte is");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 8, 0), 4, "four chunks");
    crate::testport::assert_eq(st_m(v), 0, "no miss yet");
    crate::testport::assert_eq(crate::port::src_u8(v, 5), 0, "a miss answers 0");
    crate::testport::assert_eq(st_m(v), 1, "and sets the flag");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 1, "one chunk is pending");
    crate::testport::assert_eq(crate::port::src_u8(v, 6), 0, "the same chunk again");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 1, "a chunk is recorded once");
    crate::testport::assert_eq(crate::port::src_u8(v, 0), 0, "another chunk");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 2, "two pending");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 0, 0), 2, "a fetch makes the pending chunks resident");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 0, "and nothing is pending");
    crate::testport::assert_eq(st_m(v), 1, "the view that missed stays missed");
    crate::testport::assert_eq(crate::port::src_u8(v, 5), 53, "the cache grew: the byte is there now");
    let w: &crate::port::Src = &crate::testport::src_view(base);
    crate::testport::assert_eq(st_m(w), 0, "a fresh view starts clean");
    crate::testport::assert_eq(crate::port::src_u8(w, 5), 53, "it reads the resident byte");
    crate::testport::assert_eq(crate::port::src_u8(w, 0), 48, "both resident chunks");
    crate::testport::assert_eq(st_m(w), 0, "without a miss");
    crate::testport::assert_eq(crate::port::src_u8(w, 9), 0, "a chunk still missing");
    crate::testport::assert_eq(st_m(w), 1, "misses again");
    crate::testport::assert_eq(st_m(v), 1, "and the views are independent");
}
#[test]
fn test_a_span_over_a_missing_chunk_is_zero_there_and_sets_the_flag() {
    let base: &crate::port::Src = &crate::testport::src_chunked(&crate::testport::text_blob("0123456789abcdef")[..], 4, 0);
    crate::testport::src_ctl(base, 1, 1);
    let v: &crate::port::Src = &crate::testport::src_view(base);
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(v, 4, 8)[..], 0), 52, "a resident span reads as it is");
    crate::testport::assert_eq(st_m(v), 0, "without a miss");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(v, 2, 10)[..], 2), 52, "the resident part is true");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(v, 2, 10)[..], 5), 55, "to its end");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(v, 2, 10)[..], 0), 0, "the missing head is zero");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(v, 2, 10)[..], 7), 0, "so is the missing tail");
    crate::testport::assert_eq(crate::port::blob_len(&crate::port::src_slice(v, 2, 10)[..]), 8, "the length is the span's");
    crate::testport::assert_eq(st_m(v), 1, "the flag is set");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 2, "the head and tail chunks are pending");
    crate::testport::src_ctl(base, 0, 0);
    let w: &crate::port::Src = &crate::testport::src_view(base);
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(w, 2, 10)[..], 0), 50, "after the fetch: the head");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(w, 2, 10)[..], 7), 57, "and the tail");
    crate::testport::assert_eq(st_m(w), 0, "without a miss");
}
#[test]
fn test_a_sync_source_fills_inline_and_never_misses() {
    let base: &crate::port::Src = &crate::testport::src_chunked(&crate::testport::text_blob("0123456789abcdef")[..], 4, 1);
    let v: &crate::port::Src = &crate::testport::src_view(base);
    crate::testport::assert_eq(crate::port::src_u8(v, 5), 53, "the byte, at once");
    crate::testport::assert_eq(st_m(v), 0, "no miss");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 7, 0), 1, "one chunk filled");
    crate::testport::assert_eq(crate::port::src_u8(v, 6), 54, "the same chunk");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 7, 0), 1, "is not filled twice");
    crate::testport::assert_eq(crate::port::blob_u8(&crate::port::src_slice(v, 0, 16)[..], 15), 102, "a span across every chunk");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 7, 0), 4, "fills the rest");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 0, "nothing is ever pending");
    crate::testport::assert_eq(st_m(v), 0, "no miss");
}
#[test]
fn test_named_chunks_can_be_made_to_miss() {
    let base: &crate::port::Src = &crate::testport::src_chunked(&crate::testport::text_blob("0123456789abcdef")[..], 4, 0);
    crate::testport::src_ctl(base, 3, 0);
    crate::testport::src_ctl(base, 2, 2);
    crate::testport::assert_eq(crate::testport::src_ctl(base, 5, 0), 3, "three chunks resident");
    let v: &crate::port::Src = &crate::testport::src_view(base);
    crate::testport::assert_eq(crate::port::src_u8(v, 0), 48, "chunk 0");
    crate::testport::assert_eq(crate::port::src_u8(v, 7), 55, "chunk 1");
    crate::testport::assert_eq(crate::port::src_u8(v, 15), 102, "chunk 3");
    crate::testport::assert_eq(st_m(v), 0, "none of them missed");
    crate::testport::assert_eq(crate::port::src_u8(v, 9), 0, "chunk 2 is evicted");
    crate::testport::assert_eq(st_m(v), 1, "and misses");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 1, "chunk 2 is pending");
    crate::testport::src_ctl(base, 1, 2);
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 0, "making it resident clears it");
    let w: &crate::port::Src = &crate::testport::src_view(base);
    crate::testport::assert_eq(crate::port::src_u8(w, 9), 57, "now it reads");
    crate::testport::assert_eq(st_m(w), 0, "without a miss");
}
#[test]
fn test_read_ahead_doubles_per_round() {
    let base: &crate::port::Src = &crate::testport::src_chunked(&crate::testport::text_blob("0123456789012345678901234567890123456789012345678901234567890123")[..], 4, 0);
    let v: &crate::port::Src = &crate::testport::src_view(base);
    crate::testport::assert_eq(crate::testport::src_ctl(base, 8, 0), 16, "sixteen chunks");
    crate::testport::assert_eq(crate::port::src_u8(v, 32), 0, "a miss in chunk 8");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 0, 0), 1, "round 0 fetches the chunk alone");
    crate::testport::assert_eq(crate::port::src_u8(v, 0), 0, "a miss in chunk 0");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 0, 1), 2, "round 1: one each side, clipped at the start");
    crate::testport::assert_eq(crate::port::src_u8(v, 60), 0, "a miss in chunk 15");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 0, 2), 4, "round 2: three each side, clipped at the end");
    crate::testport::assert_eq(crate::port::src_u8(v, 20), 0, "a miss in chunk 5");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 0, 5), 9, "round 5 covers what is left: sixteen less the seven resident");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 5, 0), 16, "every chunk is resident");
}
#[test]
fn test_hints_are_accepted_and_counted() {
    let base: &crate::port::Src = &crate::testport::src_chunked(&crate::testport::text_blob("0123456789abcdef")[..], 4, 0);
    let v: &crate::port::Src = &crate::testport::src_view(base);
    crate::port::src_hint(v, 0, 8);
    crate::port::src_hint(v, 8, 16);
    crate::port::src_hint(v, 4, 4);
    crate::testport::assert_eq(crate::testport::src_ctl(base, 6, 0), 3, "three hints were received");
    crate::testport::assert_eq(st_m(v), 0, "a hint never misses");
    crate::testport::assert_eq(crate::testport::src_ctl(base, 4, 0), 0, "and fetches nothing");
}
